declare(strict_types=1);
require_once __DIR__.'/TestShop.php';
use PHPUnit\Framework\TestCase;
use Sexogate\{Fulfillment,Returns,RuleViolation,Principal};
final class OperationsTest extends TestCase
{
    private function key():string{return bin2hex(random_bytes(16));}
    private function service(TestShop $s):Fulfillment{self::assertTrue(class_exists(Fulfillment::class),'Paket/sevkiyat PHP modülü eksik.');return new Fulfillment($s->f->db,$s->f->config);}
    private function packed(TestShop $s,int $quantity):array
    {$f=$this->service($s);$t=$f->prepare($s->order['orderId'],[['variantId'=>$s->variant,'quantity'=>$quantity]],$this->key(),$s->admin);$f->scan($t['id'],'TEST-01','pick',$quantity,$this->key(),$s->admin);$f->scan($t['id'],'TEST-01','pack',$quantity,$this->key(),$s->admin);return $t;}
    public function testPartialShipmentsRequirePackedQuantitiesAndDoNotDeductStockTwice():void
    {$s=new TestShop();$f=$this->service($s);$t=$this->packed($s,1);$key=$this->key();$one=$f->ship($t['id'],'Yurtiçi Kargo','OP-REFERENCE-123456',$key,$s->admin);self::assertSame($one,$f->ship($t['id'],'Yurtiçi Kargo','OP-REFERENCE-123456',$key,$s->admin));self::assertSame('partially_shipped',$one['status']);$two=$this->packed($s,1);self::assertSame('shipped',$f->ship($two['id'],'Yurtiçi Kargo','OP-REFERENCE-123457',$this->key(),$s->admin)['status']);self::assertSame(8,(int)$s->f->db->one('SELECT on_hand FROM inventory_balance WHERE variant_id=?',[$s->variant])['on_hand']);self::assertSame(2,(int)$s->f->db->one('SELECT COUNT(*) n FROM shipments')['n']);}
    public function testPackageAssignmentCannotExceedOrderAndWrongBarcodeDoesNotAdvance():void
    {$s=new TestShop(1);$f=$this->service($s);$t=$f->prepare($s->order['orderId'],[['variantId'=>$s->variant,'quantity'=>1]],$this->key(),$s->admin);try{$f->scan($t['id'],'WRONG','pick',1,$this->key(),$s->admin);self::fail('Yanlış barkod kabul edildi.');}catch(RuleViolation){}self::assertSame(0,(int)$s->f->db->one('SELECT picked_quantity FROM fulfillment_task_items')['picked_quantity']);$this->expectException(RuleViolation::class);$f->prepare($s->order['orderId'],[['variantId'=>$s->variant,'quantity'=>1]],$this->key(),$s->admin);}
    public function testOpenedReturnStaysQuarantinedAndPartialRefundIsIdempotent():void
    {$s=new TestShop();$this->service($s);self::assertTrue(class_exists(Returns::class),'İade PHP modülü eksik.');$r=new Returns($s->f->db,$s->f->config);$one=$r->request($s->order['orderId'],$s->order['trackingToken'],$s->variant,1,'Ürün inceleme talebi','opened',$this->key());$r->decide($one['id'],true,'İnceleme için kabul edildi',$this->key(),$s->admin);$r->receive($one['id'],'Depo teslim referansı123',$this->key(),$s->admin);try{$r->inspect($one['id'],'restock','Mühür açılmış durumda',$this->key(),$s->admin);self::fail('Açık iade satışa döndü.');}catch(RuleViolation){}$r->inspect($one['id'],'quarantine','İade karantinada tutuldu',$this->key(),$s->admin);$key=$this->key();$refund=$r->refund($one['id'],$key,$s->admin);self::assertEquals($refund,$r->refund($one['id'],$key,$s->admin));self::assertSame(14900,$refund['amountMinor']);$b=$s->f->db->one('SELECT on_hand,quarantine FROM inventory_balance WHERE variant_id=?',[$s->variant]);self::assertSame([8,1],[(int)$b['on_hand'],(int)$b['quarantine']]);self::assertSame(14900,(int)$s->f->db->one('SELECT refunded_minor FROM payments')['refunded_minor']);}
    public function testOtherCustomerAndWarehouseRefundAreRejected():void
    {$s=new TestShop();$this->service($s);$r=new Returns($s->f->db,$s->f->config);try{$r->request($s->order['orderId'],'wrong',$s->variant,1,'İade inceleme talebi','unknown',$this->key());self::fail('Başkasının siparişine erişti.');}catch(RuleViolation $e){self::assertSame(404,$e->status);}$this->expectException(RuleViolation::class);$r->refund('unknown',$this->key(),new Principal('depo','warehouse',true));}
    public function testAcceptedUnshippedReturnCannotStillBeDispatched():void
    {$s=new TestShop(2);$f=$this->service($s);$r=new Returns($s->f->db,$s->f->config);$request=$r->request($s->order['orderId'],$s->order['trackingToken'],$s->variant,1,'Sevk öncesi iptal talebi','unopened',$this->key());$r->decide($request['id'],true,'Sevk edilmemiş miktar iptal kabul edildi',$this->key(),$s->admin);$this->expectException(RuleViolation::class);$f->prepare($s->order['orderId'],[['variantId'=>$s->variant,'quantity'=>2]],$this->key(),$s->admin);}
    public function testReturnedShippedItemDoesNotBlockAnotherUnshippedUnit():void
    {$s=new TestShop(2);$f=$this->service($s);$task=$this->packed($s,1);$f->ship($task['id'],'Yurtiçi Kargo','OP-REFERENCE-RETURN-100',$this->key(),$s->admin);$r=new Returns($s->f->db,$s->f->config);$request=$r->request($s->order['orderId'],$s->order['trackingToken'],$s->variant,1,'Teslim sonrası iade talebi','unopened',$this->key());$r->decide($request['id'],true,'Gönderilen ürün iadesi kabul edildi',$this->key(),$s->admin);$new=$f->prepare($s->order['orderId'],[['variantId'=>$s->variant,'quantity'=>1]],$this->key(),$s->admin);self::assertSame('picking',$new['status']);}
    private function lotSale():TestShop
    {return new TestShop(1,true,function($f,$a){$catalog=new Sexogate\Catalog($f->db,$f->config);$p=$catalog->create(['name'=>'Lotlu son ürün','nameEn'=>'Last lot item','slug'=>'lot-return','category'=>'ic-giyim','sku'=>'LOT-RETURN','variantName'=>'Tek seçenek','priceMinor'=>10000,'image'=>'/media/atelier-01.svg','fixture'=>true],$a);(new Sexogate\InventoryManagement($f->db,$f->config))->tracking($p['variantId'],true,true,$a);$purchasing=new Sexogate\Purchasing($f->db,$f->config);$f->db->execute("INSERT INTO suppliers(id,name) VALUES('lot-supplier','İzole test tedarikçisi')");$po=$purchasing->create('lot-supplier','TRY',[['variantId'=>$p['variantId'],'quantity'=>1,'unitCostMinor'=>2000]],'TEST satın alma referansı',$this->key(),$a);$purchasing->receive($po['id'],[['variantId'=>$p['variantId'],'quantity'=>1,'lotNumber'=>'LOT-R-001','expiresAt'=>gmdate('Y-m-d',time()+31536000)]],'TEST lot kabul referansı',$this->key(),$a);$catalog->approve($p['id'],'TR',$a);return $p['variantId'];});}
    public function testPastLotSalePreventsDisablingTraceability():void
    {$s=$this->lotSale();$this->expectException(RuleViolation::class);(new Sexogate\InventoryManagement($s->f->db,$s->f->config))->tracking($s->variant,false,false,$s->admin);}
    public function testHistoricalRecalledLotCannotRestockEvenWithALegacyFalseTrackingFlag():void
    {$s=$this->lotSale();$f=$this->service($s);$t=$f->prepare($s->order['orderId'],[['variantId'=>$s->variant,'quantity'=>1]],$this->key(),$s->admin);$f->scan($t['id'],'LOT-RETURN','pick',1,$this->key(),$s->admin);$f->scan($t['id'],'LOT-RETURN','pack',1,$this->key(),$s->admin);$f->ship($t['id'],'Yurtiçi Kargo','OP-LOT-RETURN-101',$this->key(),$s->admin);$lot=$s->f->db->one('SELECT id FROM inventory_lots WHERE variant_id=?',[$s->variant])['id'];(new Sexogate\InventoryManagement($s->f->db,$s->f->config))->recall($lot,'TEST üretici geri çağırma referansı',$this->key(),$s->admin);$s->f->db->execute('UPDATE variants SET lot_tracking=false,expiry_required=false WHERE id=?',[$s->variant]);$r=new Returns($s->f->db,$s->f->config);$request=$r->request($s->order['orderId'],$s->order['trackingToken'],$s->variant,1,'Geri çağrılan ürün iadesi','unopened',$this->key());$r->decide($request['id'],true,'Geri çağırma iadesi kabul edildi',$this->key(),$s->admin);$r->receive($request['id'],'TEST geri çağırma teslim kaydı',$this->key(),$s->admin);$this->expectException(RuleViolation::class);$r->inspect($request['id'],'restock','Mühür sağlam görünüyor',$this->key(),$s->admin);}
}
